const D=window.DESIGN;let view=new URLSearchParams(location.search).get('view')||'home',chosenSubject=0,method='ポモドーロ',started=false,paused=false,seconds=1500,timerInterval=null;
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',chart:'M4 20V10m8 10V4m8 16v-7',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',play:'m8 4 13 8-13 8z',clock:'M12 8v5l4 2',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',list:'M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M9 15v6',arrow:'m8 5 7 7-7 7',plus:'M12 4v16M4 12h16',close:'m5 5 14 14M19 5 5 19',target:'M12 5v7l5-3',check:'m5 12 4 4L20 5',calendar:'M4 5h16v16H4zM4 10h16M8 2v6m8-6v6',pause:'M8 5v14M16 5v14',search:'m16 16 5 5'};
function ico(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${['clock','target','search'].includes(name)?'<circle cx="12" cy="12" r="8"/>':''}<path d="${icons[name]||icons.grid}"/></svg>`}
const subjects=[{name:'数学',book:'Focus Gold 数学Ⅱ＋B',time:'1h 00m',minutes:60,color:'#4368A0',week:'4h 04m'},{name:'英語',book:'必携英単語LEAP',time:'0h 40m',minutes:40,color:'#A36E42',week:'2h 40m'},{name:'物理',book:'良問の風 物理',time:'0h 30m',minutes:30,color:'#4B817B',week:'2h 06m'},{name:'化学',book:'セミナー化学',time:'記録なし',minutes:0,color:'#8E6A98',week:'1h 20m'}];
const navs={1:[['home','ホーム','home'],['analysis','学習時間','chart'],['subject','科目・教材','book'],['records','記録','list'],['manage','管理','settings']],2:[['home','ホーム','home'],['record','学習','play'],['analysis','分析','chart'],['records','記録','list'],['manage','学習管理','grid']],3:[['home','概要','grid'],['analysis','分析','chart'],['record','学習','play'],['records','記録','list'],['manage','管理','settings']],4:[['home','今日','home'],['record','学習','play'],['analysis','振り返り','chart'],['manage','ライブラリ','book']],5:[['home','今日','home'],['plan','計画','calendar'],['records','記録','list'],['analysis','分析','chart'],['manage','管理','grid']],6:[['home','全体','home'],['subject','学習室','book'],['record','学習','play'],['analysis','振り返り','chart'],['manage','管理','grid']],7:[['home','週間','calendar'],['record','学習','play'],['records','記録','list'],['analysis','分析','chart'],['manage','管理','grid']]};
function nav(where){return navs[D.id].map(([v,n,i])=>`<button aria-label="${n}" data-go="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${ico(i)}<span>${n}</span></button>`).join('')}
function section(title,action='詳しく',target='analysis'){return `<div class="section-title"><h2>${title}</h2>${action?`<button class="quiet" data-go="${target}">${action} ${ico('arrow')}</button>`:''}</div>`}
function big(){return '<div class="big-number">2<small>h</small>10<small>m</small></div>'}
function weekly(){return '<div class="weekline"><span>今週 <strong>10h 10m</strong> / 21h</span><span>あと <strong>10h 50m</strong> · 残り4日</span></div>'}
function today(ring=false){return `<section class="surface home-summary">${section('今日の学習','目標を編集','goal')}${ring?`<div class="ring"><div><span>保存済みの時間</span>${big()}<span>目標 3h · 72%</span></div></div>`:`<div class="eyebrow">TODAY / SAVED</div>${big()}<div class="spread metric-sub"><span>今日の目標 3h 00m</span><strong>あと50分</strong></div><div class="progress" role="img" aria-label="今日の目標達成率72%"><i></i></div>`}${weekly()}</section>`}
function action(title='次の学習',compact=false){return `<section class="surface actionbox"><div class="eyebrow">NEXT SESSION</div><h2>${title}</h2><p class="lead-copy">続けたい教材を選んで、そのまま計測へ。</p><label><span>科目・教材</span><select data-book aria-label="学習する教材">${subjects.map((s,i)=>`<option value="${i}" ${i===chosenSubject?'selected':''}>${s.name} · ${s.book}</option>`).join('')}</select></label><div class="method"><span>ポモドーロ · 25分 / 休憩5分</span><button class="quiet" data-go="record">変更</button></div><button class="primary" data-start>${ico('play')} ${compact?'始める':'この教材で学習を始める'}</button></section>`}
function graph(compare=false){const vals=[120,180,150,180,120,180,130],labels=['10/9','10','11','12','13','14','今日'];let bars='';vals.forEach((v,i)=>{const x=44+i*65,y=162-v/1.4;bars+=`<rect x="${x}" y="${y}" width="${compare?19:32}" height="${v/1.4}" rx="2" fill="${i===6?'var(--primary)':'var(--chart-muted)'}"/>${compare?`<rect x="${x+22}" y="${162-(v-25)/1.4}" width="19" height="${(v-25)/1.4}" rx="2" fill="var(--border)"/>`:''}<text x="${x+16}" y="184" text-anchor="middle">${labels[i]}</text>`});return `<svg class="chart-svg" viewBox="0 0 500 195" role="img" aria-label="直近7日の学習時間。今日2時間10分は途中経過。昨日まで平均2時間34分。"><text x="0" y="18">時間</text>${[0,1,2,3].map(n=>`<line x1="30" x2="495" y1="${162-n*60/1.4}" y2="${162-n*60/1.4}" stroke="var(--border)"/><text x="14" y="${166-n*60/1.4}" text-anchor="end">${n}</text>`).join('')}${bars}<line x1="30" x2="495" y1="52" y2="52" stroke="var(--muted)" stroke-dasharray="4 4"/><text x="486" y="43" text-anchor="end">平均 2h34</text></svg>`}
function chart(title='最近7日の流れ',compare=false){return `<section class="surface home-chart">${section(title)}<div><div class="chart-head"><strong>17h 40m</strong><span class="metric-sub">7日間の実績</span></div>${graph(compare)}<div class="chart-caption"><span><i class="chart-key"></i>実績 · 今日のみ途中</span><span><i class="rule-key"></i>昨日までの7日平均</span></div></div></section>`}
function subjectList(){return `<div class="subject-list">${subjects.map(s=>`<div class="subject-row"><div class="spread"><span class="name"><i class="subject-dot" style="background:${s.color}"></i>${s.name}</span><strong>${s.time}</strong></div><small>${s.book}</small><div class="mini-line"><i style="width:${s.minutes/60*100}%;background:${s.color}"></i></div></div>`).join('')}</div>`}
function subjectPanel(){return `<section class="surface home-subjects">${section('今日の科目','内訳','subject')}${subjectList()}</section>`}
function records(){return `<div>${subjects.slice(0,3).map((s,i)=>`<div class="record-row"><time>${['07:10','16:30','18:00'][i]}</time><div><p><i class="subject-dot" style="background:${s.color}"></i>${s.name}</p><small>${s.book}</small></div><strong>${s.time}</strong></div>`).join('')}</div>`}
function stats(){return `<div class="statstrip"><div><small>今日 / 保存済み</small><strong>2h 10m</strong><small>目標まで50分</small></div><div><small>今週 / 月–日</small><strong>10h 10m</strong><small>目標21h · 48%</small></div><div><small>昨日までの7日平均</small><strong>2h 34m</strong><small>今日とは途中比較</small></div><div><small>今週の残り</small><strong>10h 50m</strong><small>残り4日</small></div></div>`}
function matrix(){return `<div class="table-wrap"><table><thead><tr><th>科目</th><th>今日</th><th>今週</th><th>今日の教材</th></tr></thead><tbody>${subjects.map(s=>`<tr><td><i class="subject-dot" style="background:${s.color}"></i>${s.name}</td><td>${s.time}</td><td>${s.week}</td><td>${s.book}</td></tr>`).join('')}</tbody></table></div>`}
function timeline(){return `<div class="timeline">${subjects.slice(0,3).map((s,i)=>`<div class="timeline-item"><time>${['07:10','16:30','18:00'][i]}</time><div class="timeline-track"><i></i></div><div class="timeline-body"><p>${s.name} · ${s.book}</p><small>記録済み ${s.time} / ${['微分の復習','単語301–400','運動方程式'][i]}</small></div></div>`).join('')}<div class="timeline-item planned"><time>このあと</time><div class="timeline-track"><i></i></div><div class="timeline-body"><p>化学 · 酸化還元の例題</p><small class="planmark">予定 25分 · 新機能の表示例</small><button class="primary" data-start data-subject="3">${ico('play')}この予定から始める</button></div></div></div>`}
function bookgrid(){return `<div class="bookgrid">${subjects.map((s,i)=>`<button class="book-tile ${chosenSubject===i?'selected':''}" data-subject="${i}"><span class="book-icon" style="color:${s.color}"></span><p>${s.name}</p><small>${s.book}</small><strong>${s.time}</strong></button>`).join('')}</div>`}
function weekboard(){return `<div class="weekboard">${['月','火','水','木','金','土','日'].map((n,i)=>`<div class="daycol ${i===3?'today':i>3?'future':''}"><small>${n}${i===3?' · 今日':''}</small><span class="daynum">${12+i}</span><strong>${['3h','2h','3h','2h10','—','—','—'][i]}</strong><p>${i<4?['数学・英語','英語・物理','数学・化学','数学 / 英語 / 物理'][i]:'記録なし'}</p>${i===3?'<p>目標まであと50分</p><button class="primary" data-start>学習を始める</button>':''}</div>`).join('')}</div><div class="weekboard-mobile"><div class="miniweekly">${['月','火','水','木','金','土','日'].map((n,i)=>`<button class="${i===3?'selected':''}" data-day="${i}"><small>${n}</small>${12+i}</button>`).join('')}</div><div class="surface" id="day-detail"><div class="spread"><h2>10月15日 · 今日</h2><span class="pill">途中経過</span></div>${big()}<p class="metric-sub">目標3h · あと50分</p><button class="primary" data-start style="margin-top:15px;width:100%">${ico('play')}学習を始める</button></div></div>`}
function home(){switch(D.id){case 1:return `<div class="home-layout">${today()}${action()}${chart()}${subjectPanel()}</div>`;case 2:return `<div class="home-layout"><div class="flow-hero">${today()}${action('次の25分を始める')}</div>${chart()}${subjectPanel()}</div>`;case 3:return `<div class="labtabs"><button class="active" data-lab="overview">概要</button><button data-lab="trend">推移</button><button data-lab="subjects">科目内訳</button></div><div class="home-layout">${stats()}${chart('日別の学習時間')}${action('学習コンソール',true)}<section class="home-subjects">${section('科目別サマリー','対象を選ぶ','subject')}${matrix()}</section></div>`;case 4:return `<div class="home-layout">${today(true)}${action('教材を選んでスタート')}${chart('一週間のリズム')}${subjectPanel()}</div>`;case 5:return `<div class="home-layout"><div class="agenda-strip"><div><small>今日の記録</small>${big()}</div><div><strong>目標まであと50分</strong><p class="metric-sub">今週 10h10 / 21h</p><div class="progress"><i style="width:48%"></i></div></div><button class="primary desktop-only" data-start>${ico('play')} 学習を始める</button></div><section class="home-summary">${section('今日のタイムライン','計画を開く','plan')}${timeline()}</section><div><section class="agenda-next"><span class="newfeature">新機能の提案</span><h2 style="margin:10px 0">今日のあと50分を、2つに。</h2><p class="lead-copy">化学の例題25分、数学の復習25分。予定は実績と分けて扱います。</p></section>${chart('最近の学習ペース')}</div></div>`;case 6:return `<div class="home-layout"><div class="studio-overview"><div><small>今日の全体</small>${big()}</div><div><strong>今週 10h10 / 21h</strong><p class="metric-sub">今日の目標まで50分</p><div class="progress"><i></i></div></div></div><section class="home-subjects">${section('いつもの学習室','科目を開く','subject')}${bookgrid()}</section>${action(subjects[chosenSubject].name+'の学習を続ける')}${chart('全体の7日推移')}</div>`;case 7:return `<div class="home-layout"><div class="canvas-intro"><div><small>10月15日 木曜日 / 保存済み</small>${big()}</div><div><strong>今週 10h10 / 21h</strong><div class="progress"><i style="width:48%"></i></div><p class="metric-sub">残り4日 · あと10h50</p></div></div>${weekboard()}<div class="canvas-below">${chart('直近7日の実績')}<section class="surface">${section('今日の記録','全記録','records')}${records()}</section></div></div>`;}}
function analysis(){return `${D.id===3?'<div class="labtabs"><button class="active">時間</button><button data-go="subject">配分</button><button data-info="継続性の内訳">継続</button></div>':''}<div class="spread" style="margin-bottom:20px"><div class="segment"><button class="active" data-period="7">7日</button><button data-period="14">14日</button><button data-period="30">30日</button></div><button data-info="期間比較">${ico('calendar')}比較期間</button></div>${D.id===3?stats():`<div class="statstrip"><div><small>選択期間の合計</small><strong id="period-total">17h 40m</strong></div><div><small>今日 / 途中</small><strong>2h 10m</strong></div><div><small>昨日までの平均</small><strong>2h 34m</strong></div><div><small>比較の基準</small><strong style="font-size:18px">昨日まで</strong></div></div>`}<div class="${D.id===3?'stack':'grid2'}"><section class="surface">${section(D.id===3?'日別実績 × 前期間':'学習時間の推移','','')}<div id="period-chart">${graph(D.id===3)}</div><div class="chart-caption"><span>単位：時間 / 今日のみ途中経過</span><span>${D.id===3?'濃色：今回　薄色：比較期間（表示例）':'点線：昨日までの7日平均'}</span></div></section><section class="surface">${section('科目ごとの今日','','')}${D.id===3?matrix():subjectList()}</section></div><div class="callout">今日の2h10は一日の途中経過です。傾向の比較は昨日までの期間と分けて読みます。</div><details class="details"><summary>指標・集計期間・評価ロジックを見る</summary><p>合計・平均・Balance・Stability・Learning Conditionの既存指標をここに集約。実装時は既存の計算関数を共有し、式を変更せずに説明と表示を整えます。</p></details>`}
function record(){const s=subjects[chosenSubject];return `<div class="session"><section class="surface session-stage"><div class="segment" role="group" aria-label="記録方法">${['ストップウォッチ','ポモドーロ','手入力'].map(m=>`<button data-method="${m}" class="${method===m?'active':''}">${m}</button>`).join('')}</div><div class="pill">${s.name}</div><h2 style="margin-top:10px">${s.book}</h2>${method==='手入力'?`<div class="record-empty"><label>学習時間（分）<input type="number" value="25" min="1" aria-label="学習時間（分）"></label><label style="margin-top:12px">学習内容<input placeholder="例：例題を3問復習"></label><button class="primary" data-demo-save style="margin-top:18px">記録する（デモ）</button></div>`:`${method==='ポモドーロ'?`<div class="ring"><div><span>学習区間 · 残り</span><div class="session-clock" id="clock">${clock()}</div><span>25分 / 休憩5分</span></div></div><div class="session-labels"><span><i></i>学習 25分</span><span class="rest"><i></i>休憩 5分</span></div>`:`<p class="metric-sub" style="margin-top:30px">経過時間</p><div class="session-clock" id="clock">${clock()}</div>`}<div class="session-controls"><button class="primary" data-toggle-timer>${ico(started&&!paused?'pause':'play')}${started?(paused?'再開':'一時停止'):'計測を開始'}</button><button data-demo-save>終了して記録</button></div><p class="metric-sub">この計測は未保存 · 表示の動作確認用</p>`}</section><section class="surface session-detail">${section('今日の状況','','')}${big()}<p class="metric-sub">保存済み / 目標まであと50分</p>${weekly()}<div class="details"><h3>この教材の直近の記録</h3>${records().replaceAll('record-row','record-row')}</div><button class="quiet" data-go="home" style="margin-top:15px">ホームへ戻る</button></section></div>`}
function plan(){return `<div class="spread"><div><span class="newfeature">新機能の提案 · 現行に予定データなし</span><h2 style="margin-top:12px">今日、あと50分の組み立て</h2></div><button data-info="計画の追加">${ico('plus')}予定</button></div><div class="planboard">${['これから','取り組む','記録済み'].map((t,i)=>`<section class="planlane"><h3>${t} <span class="pill">${i===2?'3':'1'}</span></h3><article class="planitem"><span class="pill">${['化学','数学','英語'][i]}</span><h3 style="margin-top:10px">${['酸化還元の例題','微分の基本を復習','単語301–400'][i]}</h3><small>${i===2?'実績40分':'予定25分 · 実績に含めない'}</small><button ${i===2?'data-go="records"':'data-start'}>${i===2?'記録を見る':'この学習を始める'}</button></article></section>`).join('')}</div><div class="grid2" style="margin-top:24px">${chart('学習実績の流れ')}<section class="surface">${section('計画と実績を分ける','','')}<p class="lead-copy">予定の作成や完了チェックだけでは学習時間を増やしません。計測の保存、または手入力した記録を実績として集計します。</p><details class="details"><summary>新しく必要な機能</summary><p>予定ID、対象教材、学習内容、予定分数、状態、期限。採用後に保存・同期・競合の仕様を設計します。</p></details></section></div>`}
function subject(){const s=subjects[chosenSubject];return `<div class="subject-switch">${subjects.map((x,i)=>`<button data-subject="${i}" class="${i===chosenSubject?'active':''}"><i class="subject-dot" style="background:${x.color}"></i>${x.name}</button>`).join('')}</div><div class="subject-workspace"><section><div class="section-title"><h2>${s.name}の教材</h2><button class="quiet" data-info="教材の並び順">並び順</button></div><button class="book-tile selected" style="width:100%" data-info="選択中の教材"><span class="book-icon" style="color:${s.color}"></span><p>${s.book}</p><small>最後の学習：今日 · 自分の並び順</small><strong>${s.time}</strong><small>今日の学習</small></button><div class="details"><button class="quiet" data-info="教材の追加">${ico('plus')}教材を追加</button></div></section><section class="surface"><span class="eyebrow">SELECTED MATERIAL</span><h2>${s.book}</h2><div class="detail-stat"><div><small>今日</small><strong>${s.time}</strong></div><div><small>直近7日</small><strong>4h 20m</strong></div><div><small>総学習時間</small><strong>28h 24m</strong></div><div><small>使用日数</small><strong>33日</strong></div></div><p class="footnote">教材の長期値は画面構成を見るための表示例。</p><button class="primary" data-start style="width:100%;margin:18px 0">${ico('play')}この教材で学習する</button>${graph()}<details class="details"><summary>30日・90日・平均・目標・全記録</summary><p>既存の教材分析指標を省略せず、この詳細領域と期間選択に残します。</p></details></section></div>`}
function week(){return `<div class="spread"><h2>2026年10月12日 — 18日</h2><button data-go="home">今日へ</button></div>${weekly()}${weekboard()}<div class="grid2">${chart('前後の日を比較する')}<section class="surface">${section('選択日の記録','一覧','records')}${records()}</section></div>`}
function recordsScreen(){return `<div class="surface"><div class="spread" style="margin-bottom:18px"><div class="segment"><button class="active" data-filter="今日">今日</button><button data-filter="昨日">昨日</button><button data-filter="7日">7日</button></div><span class="pill" id="record-count">3件 · 2h10m</span></div><label>教材・科目・内容を検索<input id="search-records" placeholder="例：数学、LEAP"></label><div id="record-list">${records()}</div><div class="footnote">この一覧は合成データ。編集・削除の実保存は行いません。</div></div>`}
function clock(){let s=method==='ストップウォッチ'?1500-seconds:seconds;return Math.floor(s/60).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0')}
function render(){const titles={home:D.id===5?'今日を組み立てる':D.id===7?'一週間と、今日。':D.id===3?'学習の現在地':D.id===6?'今日の学習室':D.id===4?'今日も、一歩ずつ。':'今日の学習',analysis:'学習を振り返る',record:'学習セッション',subject:'科目・教材',plan:'今日の計画',week:'週キャンバス',records:'学習記録'};document.getElementById('app').innerHTML=`<div class="demo-banner"><a href="../index.html">← 7案の比較に戻る</a><span>${String(D.id).padStart(2,'0')} ${D.name} <span class="banner-note">/ 設計プロトタイプ · 合成データ · 保存・同期なし</span></span></div><div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark"><i></i><i></i><i></i></div><span>studyplus</span></div><div><div class="nav-caption">MY LEARNING</div><nav class="sidenav" aria-label="メイン">${nav()}</nav></div><div class="sidebottom"><span class="avatar">S</span>自分の学習スペース<br><br>プロトタイプ / ${D.name}</div></aside><main class="workspace"><header class="topbar"><div><div class="eyebrow">STUDYPLUS / ${view==='home'?'THURSDAY, OCT 15':'LEARNING WORKSPACE'}</div><h1>${titles[view]||titles.home}</h1><p>${view==='home'?D.tag:'状況を確認し、そのまま次の行動へ。'}</p></div><div class="topright">${[4,7].includes(D.id)?`<nav class="nav-desktop">${nav()}</nav>`:''}<span class="status"><i></i>同期済み・表示例</span><button class="iconbtn" data-go="manage" aria-label="学習管理">${ico('settings')}</button><button class="addrecord" data-go="records">${ico('plus')}記録</button></div></header><div class="screen-enter">${({home,analysis,record,subject,plan,week,records:recordsScreen}[view]||home)()}</div><footer class="footer"><span>2026年10月15日 · 合成データ</span><span>表示と導線の比較用 / 実保存・API接続なし</span></footer></main></div>${D.id===2&&view==='home'?`<div class="startdock"><div><strong>${subjects[chosenSubject].name}を学習する</strong><span>ポモドーロ · 25分</span></div><button class="primary" data-start>${ico('play')}学習を始める</button></div>`:''}<nav class="bottomnav" aria-label="メインナビゲーション">${nav()}</nav><dialog class="modal" id="modal"></dialog><div id="toast" class="toast hidden" role="status"></div>`;bind();}
function go(next){if(next==='manage'){openManage();return}if(next==='goal'){openGoal();return}view=next;const url=new URL(location.href);url.searchParams.set('view',view);history.replaceState(null,'',url);render();scrollTo(0,0)}
function message(text){const t=document.getElementById('toast');t.textContent=text;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),3000)}
function modal(content,title){const el=document.getElementById('modal');el.innerHTML=`<div class="section-title"><h2>${title}</h2><button class="iconbtn" data-close aria-label="閉じる">${ico('close')}</button></div>${content}`;el.showModal();el.querySelector('[data-close]').onclick=()=>el.close();return el}
function openManage(){const el=modal(`<p class="lead-copy" style="margin-bottom:16px">既存機能の入口を用途でまとめます。</p><div class="menu-grid">${[['subject','科目・教材'],['week','週間目標'],['records','記録の一覧'],['analysis','長期分析'],['exams','模試'],['ai','AI分析'],['sync','同期・JSON'],['settings','設定']].map(([id,n])=>`<button data-dest="${id}">${ico(id==='subject'?'book':id==='records'?'list':'grid')}${n}</button>`).join('')}</div>`,'学習管理');el.querySelectorAll('[data-dest]').forEach(b=>b.onclick=()=>{el.close();if(['subject','week','records','analysis'].includes(b.dataset.dest))go(b.dataset.dest);else modal('<p>この機能は現行アプリから保持する入口です。今回のモック対象はホームと主要画面です。</p><p class="footnote">実装時は既存の分析項目・保存・同期機能へ接続します。</p>',b.textContent.trim())})}
function openGoal(){const el=modal('<p class="lead-copy">直接設定が優先。未設定時は曜日・週間目標から目安を表示します。</p><label>今日の目標（分）<input type="number" value="180" min="1" max="1440"></label><button class="primary" id="goal-save">設定を確認（デモ）</button>','今日の目標');el.querySelector('#goal-save').onclick=()=>{el.close();message('目標設定の導線です。データは保存していません。')}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-book]').forEach(el=>el.onchange=()=>{chosenSubject=Number(el.value);const dock=document.querySelector('.startdock strong');if(dock)dock.textContent=subjects[chosenSubject].name+'を学習する'});document.querySelectorAll('[data-subject]').forEach(el=>{if(!el.hasAttribute('data-start'))el.onclick=()=>{chosenSubject=Number(el.dataset.subject);render()}});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{if(b.dataset.subject)chosenSubject=Number(b.dataset.subject);started=true;paused=false;if(!timerInterval)timerInterval=setInterval(()=>{if(started&&!paused&&seconds>0){seconds--;const el=document.getElementById('clock');if(el)el.textContent=clock()}},1000);go('record')});document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;started=false;paused=false;seconds=1500;render()});document.querySelectorAll('[data-toggle-timer]').forEach(b=>b.onclick=()=>{if(!started){started=true;if(!timerInterval)timerInterval=setInterval(()=>{if(started&&!paused&&seconds>0){seconds--;const el=document.getElementById('clock');if(el)el.textContent=clock()}},1000)}else paused=!paused;render()});document.querySelectorAll('[data-demo-save]').forEach(b=>b.onclick=()=>{started=false;paused=false;seconds=1500;message('記録の確認までのデモです。実際の保存・同期は行いません。')});document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>modal('<p>この操作の入口を確認するためのモックです。</p><p class="footnote">詳細仕様は案の選定後に既存機能と統合します。</p>',b.dataset.info));document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('period-chart').innerHTML=graph(b.dataset.period!=='7');const t=document.getElementById('period-total');if(t)t.textContent=({'7':'17h 40m','14':'34h 20m','30':'72h 10m'})[b.dataset.period];message(b.dataset.period+'日表示の見本。7日以外の数値は構成確認用です。')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));const l=document.getElementById('record-list');l.innerHTML=b.dataset.filter==='昨日'?records().replaceAll('07:10','昨日').replaceAll('16:30','昨日').replaceAll('18:00','昨日'):records();message(b.dataset.filter+'の記録表示・デモ')});document.getElementById('search-records')?.addEventListener('input',e=>{document.querySelectorAll('.record-row').forEach(row=>row.hidden=!row.textContent.includes(e.target.value))});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-day]').forEach(x=>x.classList.toggle('selected',x===b));const day=Number(b.dataset.day),el=document.getElementById('day-detail');el.innerHTML=`<h2>10月${12+day}日 ${day===3?'· 今日':''}</h2><div class="big-number">${['3h','2h','3h','2h10','—','—','—'][day]}</div><p class="metric-sub">${day>3?'まだ記録はありません。予定と実績は分けます。':day===3?'途中経過 · 目標まで50分':'保存済みの実績'}</p><button class="primary" id="day-action" style="margin-top:15px">${day===3?'学習を始める':'記録を見る'}</button>`;document.getElementById('day-action').onclick=()=>go(day===3?'record':'records')});document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-lab]').forEach(x=>x.classList.toggle('active',x===b));const type=b.dataset.lab;document.querySelector('.home-chart').classList.toggle('hidden',type==='subjects');document.querySelector('.home-subjects').classList.toggle('hidden',type==='trend')})}
render();
